<script setup lang="ts">import {resultPresentation} from '../domain/controllers';import type {Workbench} from '../app/useWorkbench';import JsonReport from '../shared/JsonReport.vue';import {openPath} from '../shared/desktop';const {w}=defineProps<{w:Workbench}>();const s=w.s;const verdicts:Record<string,string>={success:'成功',partial:'部分成功',no_update:'无模型更新',unconfirmed:'未确认',failed:'失败',cancelled:'已取消',pending:'处理中'};</script>
<template><div class="page-heading"><div><div class="eyebrow">RUN & RESULTS</div><h1>执行计算，核验真实结果</h1><p>进程退出、产物完整性与业务结论分层呈现。</p></div><el-tag :type="s.runtime.busy?'warning':'info'">{{s.runtime.busy?'后台执行中':'当前空闲'}}</el-tag></div><section class="card run-command"><div><div class="eyebrow">CURRENT RUNTIME</div><h2>{{s.job?.name||'尚未加载运行配置'}}</h2><code>{{s.job?s.job.schema+'  -f '+s.job.func+'  -t '+s.job.taskId:'选择或装配运行 XML 后开始'}}</code><p v-if="s.job?.outDir" class="mono">实际输出：{{s.job.outDir}}</p></div><div class="run-actions"><el-button type="primary" size="large" data-testid="run" @click="w.startRun" :disabled="!!w.runReason.value">开始运行</el-button><el-button type="danger" plain size="large" @click="w.cancel" :disabled="!s.runtime.busy||s.runtime.external||!s.runtime.sid">取消当前任务</el-button><small>{{w.runReason.value||'当前配置已通过检查'}}</small></div></section><section v-if="s.runtime.busy" class="card"><div class="section-line"><h2>锁定的执行上下文</h2><span class="status-pill busy"><i/>{{s.runtime.phase||'准备中'}}</span></div><p>{{s.runtime.external?'其他平台实例正在操作相关资源。':s.runtime.label||'正在执行本次任务，进程收尾与归档期间继续锁定资源。'}}</p><dl class="definition-list"><dt>固定会话</dt><dd>{{s.runtime.sid||s.resultSid||'准备中'}}</dd><dt>实际功能</dt><dd>{{s.runtime.func||s.runContext?.func||'工具任务'}}</dd><dt>关联项目</dt><dd class="mono">{{s.runContext?.project||s.state.project}}</dd></dl><el-button @click="w.showRuntimeLog">展开持续日志</el-button></section><section class="card"><div class="card-heading"><span class="card-icon teal">R</span><div><h2>结果核验与文件</h2><p>固定会话提供本次证据；目录浏览会明确标注未关联运行</p></div><el-button @click="w.loadResults" :disabled="!!s.pending">读取结果</el-button></div><div class="result-query"><el-input v-model="s.resultJob" placeholder="可选：按任务名浏览目录"/><el-checkbox v-model="s.directoryOnly">仅浏览任务目录</el-checkbox><el-tag v-if="s.resultSid&&!s.directoryOnly">固定会话 {{s.resultSid}}</el-tag></div><template v-if="s.result"><div class="outcome-head"><el-tag size="large" :type="resultPresentation(s.result).type" effect="dark">{{resultPresentation(s.result).label}}</el-tag><strong>{{s.result.historical?'历史会话：当时结论与当前文件分别核对':s.result.associated===false?'目录浏览 · 未关联本次运行':'会话结果已关联'}}</strong><span v-if="s.result.historical">当前文件：{{typeof s.result.current_files==='string'?s.result.current_files:s.result.current_files?.status||'查看核验详情'}}</span></div><div class="outcome-grid"><div><span>01 · PROCESS</span><h3>进程状态</h3><p>{{s.result.process?.status||s.result.status||'未记录'}}</p><small>退出码 {{s.result.process?.exit??s.result.exit??'未记录'}}</small></div><div><span>02 · ARTIFACTS</span><h3>产物完整性</h3><p>{{s.result.artifacts?.status||s.result.artifacts?.verdict||'按结果报告核验'}}</p><small>{{s.result.artifacts?.message||s.result.validation?.message||'文件存在不单独等同于计算成功'}}</small></div><div><span>03 · BUSINESS</span><h3>业务结论</h3><p>{{verdicts[s.result.verdict]||'未确认'}}</p><small>{{s.result.message||s.result.business?.message||'依据本次关联产物与功能验证规则判断'}}</small></div></div><p v-if="s.result.dir" class="result-directory mono">实际输出 {{s.result.dir}}</p><div class="button-row"><el-button @click="openPath(s.result.dir)" :disabled="!s.result.dir||s.result.exists===false">打开输出目录</el-button><el-button @click="openPath(s.result.archive?.dir||s.result.archive_dir)" :disabled="!s.result.archive?.dir&&!s.result.archive_dir">打开本次归档</el-button><el-button @click="w.attachLog(s.resultSid,!!s.result.historical)" :disabled="!s.resultSid">查看固定会话日志</el-button></div><el-table :data="s.result.files||[]" max-height="380" empty-text="没有可展示的当前文件；历史归档与当时结论仍可查看"><el-table-column prop="rel" label="结果文件" min-width="300"/><el-table-column prop="size" label="大小" width="150"/></el-table><JsonReport :data="s.result" title="查看分级核验、历史匹配和归档完整报告"/></template><el-empty v-else :description="s.runtime.busy&&s.resultSid?'等待固定会话 '+s.resultSid+' 的结果验证，之前会话的结论不会用于本次运行':'运行后读取固定会话结果，或输入任务名浏览现有目录'" :image-size="85"/></section></template>
